// Parse all price data and check against thresholds
// Edit thresholds here or load from external config

const config = {
  // CRYPTO THRESHOLDS
  crypto: {
    BTC: {
      name: 'Bitcoin',
      above: 100000,
      below: 85000,
      percent_change_24h: 8
    },
    SOL: {
      name: 'Solana', 
      above: 200,
      below: 120,
      percent_change_24h: 10
    }
  },
  // STOCK THRESHOLDS
  stocks: {
    TSLA: {
      name: 'Tesla',
      above: 450,
      below: 350,
      percent_change: 5
    },
    'GC=F': {
      name: 'Gold Futures',
      above: 2800,
      percent_change: 3
    }
  },
  // SETTINGS
  cooldown_hours: 4,
  jarvis_api: 'http://192.168.70.228:8880'
};

// Get input data from all HTTP requests
const cryptoData = $('Fetch Crypto Prices').first().json;
const tslaData = $('Fetch TSLA').first().json;
const goldData = $('Fetch Gold').first().json;

const alerts = [];
const now = new Date().toISOString();

// Check BTC
if (cryptoData.bitcoin) {
  const btc = cryptoData.bitcoin;
  const price = btc.usd;
  const change24h = btc.usd_24h_change;
  const cfg = config.crypto.BTC;

  if (cfg.above && price >= cfg.above) {
    alerts.push({
      title: `BTC Price Alert: $${price.toLocaleString()}`,
      description: `Bitcoin hit $${cfg.above.toLocaleString()}! Current price: $${price.toLocaleString()} (${change24h > 0 ? '+' : ''}${change24h.toFixed(2)}% 24h)`,
      severity: 'high',
      source: 'price_monitor',
      metadata: { symbol: 'BTC', price, threshold: cfg.above, type: 'above' }
    });
  }
  if (cfg.below && price <= cfg.below) {
    alerts.push({
      title: `BTC Price Alert: $${price.toLocaleString()}`,
      description: `Bitcoin dropped below $${cfg.below.toLocaleString()}! Current: $${price.toLocaleString()}`,
      severity: 'medium',
      source: 'price_monitor',
      metadata: { symbol: 'BTC', price, threshold: cfg.below, type: 'below' }
    });
  }
  if (cfg.percent_change_24h && Math.abs(change24h) >= cfg.percent_change_24h) {
    alerts.push({
      title: `BTC Volatility Alert: ${change24h > 0 ? '+' : ''}${change24h.toFixed(2)}%`,
      description: `Bitcoin moved ${Math.abs(change24h).toFixed(2)}% in 24 hours. Price: $${price.toLocaleString()}`,
      severity: 'high',
      source: 'price_monitor',
      metadata: { symbol: 'BTC', price, change_24h: change24h, type: 'percent_change' }
    });
  }
}

// Check SOL
if (cryptoData.solana) {
  const sol = cryptoData.solana;
  const price = sol.usd;
  const change24h = sol.usd_24h_change;
  const cfg = config.crypto.SOL;

  if (cfg.above && price >= cfg.above) {
    alerts.push({
      title: `SOL Price Alert: $${price.toFixed(2)}`,
      description: `Solana above $${cfg.above}! Current: $${price.toFixed(2)}`,
      severity: 'medium',
      source: 'price_monitor',
      metadata: { symbol: 'SOL', price, threshold: cfg.above, type: 'above' }
    });
  }
  if (cfg.below && price <= cfg.below) {
    alerts.push({
      title: `SOL Price Alert: $${price.toFixed(2)}`,
      description: `Solana dropped below $${cfg.below}! Current: $${price.toFixed(2)}`,
      severity: 'medium',
      source: 'price_monitor',
      metadata: { symbol: 'SOL', price, threshold: cfg.below, type: 'below' }
    });
  }
  if (cfg.percent_change_24h && Math.abs(change24h) >= cfg.percent_change_24h) {
    alerts.push({
      title: `SOL Volatility Alert: ${change24h > 0 ? '+' : ''}${change24h.toFixed(2)}%`,
      description: `Solana moved ${Math.abs(change24h).toFixed(2)}% in 24 hours`,
      severity: 'high',
      source: 'price_monitor',
      metadata: { symbol: 'SOL', price, change_24h: change24h, type: 'percent_change' }
    });
  }
}

// Check TSLA
if (tslaData.chart?.result?.[0]) {
  const result = tslaData.chart.result[0];
  const meta = result.meta;
  const price = meta.regularMarketPrice;
  const prevClose = meta.previousClose || meta.chartPreviousClose;
  const change = prevClose ? ((price - prevClose) / prevClose) * 100 : 0;
  const cfg = config.stocks.TSLA;

  if (cfg.above && price >= cfg.above) {
    alerts.push({
      title: `TSLA Price Alert: $${price.toFixed(2)}`,
      description: `Tesla above $${cfg.above}! Current: $${price.toFixed(2)} (${change > 0 ? '+' : ''}${change.toFixed(2)}%)`,
      severity: 'medium',
      source: 'price_monitor',
      metadata: { symbol: 'TSLA', price, threshold: cfg.above, type: 'above' }
    });
  }
  if (cfg.below && price <= cfg.below) {
    alerts.push({
      title: `TSLA Price Alert: $${price.toFixed(2)}`,
      description: `Tesla dropped below $${cfg.below}! Current: $${price.toFixed(2)}`,
      severity: 'medium',
      source: 'price_monitor',
      metadata: { symbol: 'TSLA', price, threshold: cfg.below, type: 'below' }
    });
  }
  if (cfg.percent_change && Math.abs(change) >= cfg.percent_change) {
    alerts.push({
      title: `TSLA Volatility Alert: ${change > 0 ? '+' : ''}${change.toFixed(2)}%`,
      description: `Tesla moved ${Math.abs(change).toFixed(2)}% today. Price: $${price.toFixed(2)}`,
      severity: 'high',
      source: 'price_monitor',
      metadata: { symbol: 'TSLA', price, change_percent: change, type: 'percent_change' }
    });
  }
}

// Check Gold
if (goldData.chart?.result?.[0]) {
  const result = goldData.chart.result[0];
  const meta = result.meta;
  const price = meta.regularMarketPrice;
  const prevClose = meta.previousClose || meta.chartPreviousClose;
  const change = prevClose ? ((price - prevClose) / prevClose) * 100 : 0;
  const cfg = config.stocks['GC=F'];

  if (cfg.above && price >= cfg.above) {
    alerts.push({
      title: `Gold Price Alert: $${price.toFixed(2)}`,
      description: `Gold above $${cfg.above}/oz! Current: $${price.toFixed(2)}`,
      severity: 'medium',
      source: 'price_monitor',
      metadata: { symbol: 'GC=F', price, threshold: cfg.above, type: 'above' }
    });
  }
  if (cfg.percent_change && Math.abs(change) >= cfg.percent_change) {
    alerts.push({
      title: `Gold Volatility Alert: ${change > 0 ? '+' : ''}${change.toFixed(2)}%`,
      description: `Gold moved ${Math.abs(change).toFixed(2)}% today. Price: $${price.toFixed(2)}/oz`,
      severity: 'high',
      source: 'price_monitor',
      metadata: { symbol: 'GC=F', price, change_percent: change, type: 'percent_change' }
    });
  }
}

// Return alerts (or empty if none triggered)
return alerts.length > 0 ? alerts.map(a => ({ json: a })) : [{ json: { no_alerts: true } }];
